"use strict";(self.webpackChunktest_website=self.webpackChunktest_website||[]).push([[548061],{63015:(e,t,a)=>{a.r(t),a.d(t,{assets:()=>h,contentTitle:()=>s,default:()=>c,frontMatter:()=>r,metadata:()=>n,toc:()=>l});var n=a(669114),i=a(474848),o=a(28453);const r={tags:["UFO","2025-04"]},s="Ubatuba \u306e\u843d\u4e0b\u7269\u306e\u5206\u6790\u7d50\u679c",h={authorsImageUrls:[]},l=[{value:"\u524d\u7f6e\u304d",id:"\u524d\u7f6e\u304d",level:2},{value:"\u52d5\u753b(20:09)",id:"\u52d5\u753b2009",level:2},{value:"\u52d5\u753b\u6982\u8981\u6b04",id:"\u52d5\u753b\u6982\u8981\u6b04",level:3},{value:"link2",id:"link2",level:2},{value:"\u51fa\u5178",id:"\u51fa\u5178",level:3},{value:"\u539f\u6587",id:"\u539f\u6587",level:3},{value:"link3",id:"link3",level:2},{value:"\u51fa\u5178",id:"\u51fa\u5178-1",level:3},{value:"\u539f\u6587",id:"\u539f\u6587-1",level:3},{value:"link4",id:"link4",level:2},{value:"\u51fa\u5178",id:"\u51fa\u5178-2",level:3},{value:"\u539f\u6587",id:"\u539f\u6587-2",level:3},{value:"link5",id:"link5",level:2},{value:"\u51fa\u5178",id:"\u51fa\u5178-3",level:3},{value:"link6",id:"link6",level:2},{value:"\u51fa\u5178",id:"\u51fa\u5178-4",level:3},{value:"link7",id:"link7",level:2},{value:"\u51fa\u5178",id:"\u51fa\u5178-5",level:3}];function d(e){const t={a:"a",h2:"h2",h3:"h3",hr:"hr",li:"li",ol:"ol",p:"p",ul:"ul",...(0,o.R)(),...e.components},{Details:a}=t;return a||function(e,t){throw new Error("Expected "+(t?"component":"object")+" `"+e+"` to be defined: you likely forgot to import, pass, or provide it.")}("Details",!0),(0,i.jsxs)(i.Fragment,{children:[(0,i.jsx)(t.h2,{id:"\u524d\u7f6e\u304d",children:"\u524d\u7f6e\u304d"}),"\n",(0,i.jsx)(t.p,{children:"\u53c2\u8003\u8cc7\u6599\u3068\u3057\u3066\u8a18\u9332\u3002"}),"\n",(0,i.jsx)(t.h2,{id:"\u52d5\u753b2009",children:"\u52d5\u753b(20:09)"}),"\n",(0,i.jsx)(t.p,{children:"Exploded UFO (Ubatuba, Brazil, 1957) material analysis discussed in a radio broadcast from 1964"}),"\n",(0,i.jsx)("iframe",{width:"560",height:"315",src:"https://www.youtube.com/embed/KdfdE9sQ2qo?si=McuUIFAxspMPRxNU",title:"YouTube video player",frameborder:"0",allow:"accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share",referrerpolicy:"strict-origin-when-cross-origin",allowfullscreen:!0}),"\n",(0,i.jsx)(t.p,{children:(0,i.jsx)(t.a,{href:"http://www.youtube.com/watch?v=KdfdE9sQ2qo",children:"www.youtube.com/watch?v=KdfdE9sQ2qo"})}),"\n",(0,i.jsx)(t.h3,{id:"\u52d5\u753b\u6982\u8981\u6b04",children:"\u52d5\u753b\u6982\u8981\u6b04"}),"\n",(0,i.jsx)(t.p,{children:"6,400 views  Aug 26, 2024  #brazil #ubatuba\r\nWalter Webb (NICAP) and John Hopf (APRO) are discussing the material analysis of an alleged 1957 UFO crash/explosion in Ubatuba, Brazil, and talking about the \u2018phenomenon\u2019."}),"\n",(0,i.jsx)(t.p,{children:'MORE INFORMATION ON THE UBATUBA UFO INCIDENT:\r\n"The Ubatuba Incident"'}),"\n",(0,i.jsxs)(t.p,{children:['"Coral Lorenzen & the Ubatuba Fragments (by Robert Barrow)" ',(0,i.jsx)(t.a,{href:"http://www.nicap.org/reports/uba1.htm",children:"http://www.nicap.org/reports/uba1.htm"}),'\r\n"Dow Chemical and the Scientific Analysis of UFO Debris" ',(0,i.jsx)(t.a,{href:"http://www.nicap.org/reports/ubatubad",children:"http://www.nicap.org/reports/ubatubad"}),'...\r\n"Composition of the Brazil Magnesium (Dr. Peter Sturrock)" ',(0,i.jsx)(t.a,{href:"http://www.nicap.org/reports/ubatuban",children:"http://www.nicap.org/reports/ubatuban"}),'...\r\n"On Events Possibly Related to the \u2018\u2018Brazil Magnesium\u2019\u2019" ',(0,i.jsx)(t.a,{href:"http://www.nicap.org/papers/scientifi",children:"http://www.nicap.org/papers/scientifi"}),'...\r\n"Ubatuba [was: Michael Wolf\'s Samples in Italy] (Gildais Bourdais)" ',(0,i.jsx)(t.a,{href:"http://www.nicap.org/reports/ubatubag",children:"http://www.nicap.org/reports/ubatubag"}),"..."]}),"\n",(0,i.jsx)(t.p,{children:(0,i.jsx)(t.a,{href:"https://www.ufocasebook.com/ubatuba.html",children:"https://www.ufocasebook.com/ubatuba.html"})}),"\n",(0,i.jsx)(t.p,{children:'"UFO explosion fragments from Ubatuba, Brazil | Garry Nolan and Lex Fridman"    \u2022 UFO explosion fragments from Ubatuba,...'}),"\n",(0,i.jsx)(t.p,{children:"Thumbnail background photo for illustration purposes only!"}),"\n",(0,i.jsx)(t.p,{children:"THIS VIDEO IS FOR EDUCATIONAL PURPOSE ONLY!\r\nFAIR USE PRINCIPLES UNDER SECTION 107 OF THE COPYRIGHT ACT."}),"\n",(0,i.jsxs)(t.p,{children:["If you appreciate the content on my channel and would like to support me, please visit:\r\n",(0,i.jsx)(t.a,{href:"https://www.buymeacoffee.com/eyesoncineW",children:"https://www.buymeacoffee.com/eyesoncineW"}),"\r\nThanks, EOC"]}),"\n",(0,i.jsxs)(a,{children:[(0,i.jsx)("summary",{children:"\u25bc\u5c55\u958b"}),(0,i.jsx)(t.p,{children:"Well now, generally speaking then, various kinds of objects apparently have been identified by witnesses.\r\nThere have been the saucer shapes, and this is the most popular version.\r\nThere have been the long cigar-shaped affairs.\r\nAnd there have been round globes, which seem to hover over cars and stop their ignitions, as you mentioned.\r\nThis has happened to railroads.\r\nPlanes have had trouble.\r\nThere have been many pilots to report that their whole electrical systems went out in seeing some such thing,and then only in the nick of time does it come back.\r\n(00:00:28)"}),(0,i.jsx)(t.p,{children:"Some planes have been lost completely unexplainably.\r\nWhole squadrons of planes have disappeared, where there has been a rise in magnetic activity.\r\nAll of these things tend to, in a peculiar sort of way, corroborate one another, or at least lead to similar questions.\r\nAm I overstating the case here?\r\nWell, that's quite correct, and as you mentioned, there seem to be quite a variety of types of these UFOs.\r\n(00:00:55)"}),(0,i.jsx)(t.p,{children:"All right, gentlemen, we're just about time to get up to the news.\r\nImmediately after the news, I want to go into one other matter,and I think you had some concern with this, Mr. Hoff, or at least know something about it.\r\nPerhaps you do too, Mr. Webb.\r\nOne object that was seen to get into trouble and explode down over Brazil,and chunks of this object, made of whatever, fell into a lake,and they recovered some of these pieces, and there have been numerous tests done on them.\r\n(00:01:22)"}),(0,i.jsx)(t.p,{children:"And I want to get into what that test showed.\r\nPerhaps some conclusions that we can make very early,and without all of the information that both of your organizations certainly have on file.\r\nAnd then you want to open up the phones to anybody who has any other stories,and I suppose you would welcome this.\r\nMaybe we can add to the file of both NICAP and APRO.\r\n(00:01:39)"}),(0,i.jsx)(t.p,{children:"And this is something I know you're both looking for.\r\nAnd questions or comments or curled lips, we're open to them all.\r\nSo we'll see you in five.\r\nMeantime, the magic word is UFO.\r\nUnknown flying objects.\r\nAre they real? Are they imaginary?\r\nMy two guests this evening, Walter Webb and John Hopf,both believe, though they are natural skeptics, but also they're scientists in their fields.\r\n(00:02:06)"}),(0,i.jsx)(t.p,{children:"One a professional photographer, the other a lecturer in astronomy.\r\nBoth very much interested in the subject,and they believe there is something out there that has not been adequately explained.\r\nWe've been talking about this for some time here on Nightline,but right now we want to get to some facts.\r\nNow, Mr. Hopf, I believe it was in 1957 that a most unusual occurrence took place down in BrazilNow, Mr.\r\n(00:02:29)"}),(0,i.jsx)(t.p,{children:"Hopf, I believe it was in 1957 that a most unusual occurrence took place down in Brazilat a place known as Ubatuba. I think I'm pronouncing it right.\r\nU-B-A-T-U-B-A. Looks like Ubatuba, but I guess they say Ubatuba.\r\nSomething like that.\r\nApparently, an unknown flying object, a flying saucer,attempted to make a maneuver that was even a little too much for them and exploded.\r\n(00:02:47)"}),(0,i.jsx)(t.p,{children:"Not very far above, a beach and a lake and pieces of this object fell down and were recovered.\r\n(00:02:55)"}),(0,i.jsx)(t.hr,{}),(0,i.jsx)(t.p,{children:"Great tests were done by those, by physicists and chemical analysis and radiological analysis and I don't know what all.\r\nMetallurgists.\r\nMetallurgists and so forth, and a very scientific investigation that took quite some time,and they made more than one test.\r\nAnd what was proved that this material was made of?\r\nWell, a series of tests were made by the Brazilian Mineral Resources Board,which had some excellent laboratory facilities.\r\n(00:03:27)"}),(0,i.jsx)(t.p,{children:"They made a number of spectroscopic tests on two or three different types of machines,and the results were very conclusive that this material was magnesium of a puritybeyond what we consider laboratory standard.\r\nAnd at that time, I don't believe that any...\r\nIn fact, I know no metal fabricating plant in the world would have made metal of this purityin a quantity that would be required to build any sort of a flying device.\r\n(00:04:06)"}),(0,i.jsx)(t.p,{children:"Of course, there'd be no sense in making, as far as we could see,in making any sort of flying machine out of pure magnesium.\r\nFirst of all, it isn't the strongest thing in the world.\r\nThat's right.\r\nAnd has all kinds of qualities that we would consider absolutely impossible.\r\nWell, it's quite ridiculous to make anything out of magnesium of almost 100% purity.\r\nThe most refined tests that were conducted on this material by the Brazilian Mineral Resources Boardfailed to show any impurities.\r\n(00:04:34)"}),(0,i.jsx)(t.p,{children:"The purity was beyond any laboratory standard samples that they had.\r\nI understand that recently additional tests were made in this country by a number of...\r\nby at least two laboratories.\r\nOne laboratory of the Atomic Energy Commissionand another one by an independent chemical company laboratory.\r\nAnd these tests confirm the findings of the Brazilian laboratoriesthat this material was definitely not a man-made material.\r\n(00:05:13)"}),(0,i.jsx)(t.p,{children:"Now, I'm not a metallurgist. I'm really out of my field here.\r\nHowever, I talked to Dr. Fontes. He came here to Boston to meet me a year ago.\r\nThat is a scientist in Brazil who is also interested in unknown...\r\nThat's right. I'm sorry. We hadn't gotten into that.\r\nBut Dr. Fontes followed through these reports and tests very exhaustively.\r\nAnd after talking with him, I was completely convinced that there is no question of the...\r\n(00:05:42)"}),(0,i.jsx)(t.p,{children:"the fact that these tests were authentic and indisputably accurate.\r\nAnd consequently, this material seemed to show that it had an extraterrestrial... terrestrial...\r\nI can never say that word.\r\nThere wasn't any question that this material...\r\nNow, if you like, I could go into the...\r\nwhat happened when we sent samples of this material to the United States government.\r\nYes, what did?\r\nDo you want to go into that now?\r\n(00:06:07)"}),(0,i.jsx)(t.p,{children:"Sure.\r\nOne sample was sent to the United States Air Force.\r\nAnd this sample was accidentally burned up in the spectroscope due to some error of the operator.\r\nI'm not familiar with the operation of the spectroscopic machines.\r\nBut another sample was then requested.\r\nAnd this second sample... am I right here, Walter?\r\nThe second sample was tested in a contaminated machine.\r\n(00:06:37)"}),(0,i.jsx)(t.hr,{}),(0,i.jsx)(t.p,{children:"In other words, in order to determine...\r\nYes.\r\nIn order to determine the purity of the material...\r\nThe electrodes themselves enter into it.\r\nWell, it seemed that a previous test had been made in the machine and the fragments...\r\nthe machine had not been correctly cleaned.\r\nYou see, in order to detect impurities of a very fine degree by a test of this type,the machine must be completely cleaned in a manner that's completely beyond our ordinary standards of cleanliness.\r\n(00:07:07)"}),(0,i.jsx)(t.p,{children:"So what you're saying is that the second test...\r\nWas inconclusive.\r\nIt showed traces of materials that were the result of the fact that these materials had been left in the testing apparatus.\r\nThe Air Force then requested more samples.\r\nAnd, of course, we drew the line here.\r\nI don't know how many pieces of this material are still on hand, but I know we had a number of fragments.\r\n(00:07:30)"}),(0,i.jsx)(t.p,{children:"It was completely pure magnesium.\r\nYes, the various tests that have been made certainly show this.\r\nMr. Stone is with us, and we'll get to him in just a moment.\r\nMr. Stone, you're on WEI's nightline. Go right ahead.\r\nAll right, I was going to ask two questions.\r\nThe first was going to be dealing with ball lightning, but that's been preempted already.\r\nAnd the second was going to be a question about the weight and size of the magnesium sample referred to in tonight's conversation.\r\n(00:08:01)"}),(0,i.jsx)(t.p,{children:"All right. Mr. Hoppe, I think, has that.\r\nI don't have the figures right in front of me.\r\nI believe these samples were varied from a fraction of an inch to two or three inches in size.\r\nAll right.\r\nI'm not sure of the weight.\r\nOkay, now you made some statements about it not being man-made.\r\nYes.\r\nWell, you can make metals or semiconductors or anything you want.\r\n(00:08:26)"}),(0,i.jsx)(t.p,{children:"I've almost unlimited purity nowadays in laboratories and ultimately very large quantities.\r\nSo I don't see how you can come to the conclusion about its man-made nature or non-man-made nature.\r\nWell, I realize that metallurgical science has improved quite a bit in the last few years.\r\nHowever, at the time of this sighting and at the time these fragments were picked up, no one in the world, to our knowledge,either had the facilities or the need or the desire to make pure magnesium in a quantity that would be required to make a flying device.\r\n(00:09:03)"}),(0,i.jsx)(t.p,{children:"Okay, now what was the year?\r\n1957, wasn't it, Mr. Hoppe?\r\nOkay, and can you give an estimate of any purity estimate at all of the magnesium?\r\nWell, let's see. The entire report's right in front of me, but I don't know whether I can take the time to go through the entire report.\r\nAs I say, I'm not a metallurgist. However, I'd recommend that you get a copy of the book, which has an exhaustive treatment of it.\r\n(00:09:28)"}),(0,i.jsx)(t.p,{children:"The title of the book is The Great Flying Saucer Hoax, published by William Frederick Press, New York.\r\nAnd any book dealer can get this for you. If you're interested in this angle, I'd recommend that you get it.\r\n(00:09:42)"}),(0,i.jsx)(t.hr,{}),(0,i.jsx)(t.p,{children:"The metallurgical report itself occupies certainly 50 or 60 pages.\r\nI think I have just found one thing here that maybe I can give you.\r\nThis one report, sir, Mr. Stone.\r\nAn emission spectrograph test showed the presence of trace elements to this amount.\r\nNow, wait a minute. That's the one here in the United States. That one was no good.\r\nWhy was it listed as contaminated?\r\n(00:10:09)"}),(0,i.jsx)(t.p,{children:"Because of the electrodes, I guess.\r\nWell, no tests were made by the government in this country that were properly conducted.\r\nOkay, now, who says that these things were not properly conducted? What is the criterion?\r\nIn other words, you were about to quote an emission spectrograph reading.\r\nYes, I was looking at the wrong one, sir. I'm sorry.\r\nAll right, then let me go...\r\nThis seems to be, to my mind, something foggy about this.\r\n(00:10:39)"}),(0,i.jsx)(t.p,{children:"You mentioned in the course of your conversation that the AEC had performed tests on the magnesium. Is that correct?\r\nYes, yes, recently.\r\nThe original tests performed under Air Force auspices were aborted for one or two reasons.\r\nIn one case, they burned up the sample accidentally, and I should say the sample was destroyed before the test could be properly set up.\r\nI'm not sure what the procedure is to test metal samples, but the sample was destroyed accidentally.\r\n(00:11:14)"}),(0,i.jsx)(t.p,{children:"In the second test, it was discovered after the test was completed that the machine was contaminated with the results of a previous test.\r\nAll right, now, what laboratory did that? What Air Force laboratory?\r\nI'm not sure, but it was conducted under official government sponsorship.\r\nOkay, can you mention, perhaps, what the results of the AEC tests were?\r\nWell, this gets a little complex, Mr. Stone.\r\n(00:11:38)"}),(0,i.jsx)(t.p,{children:"The more recent tests confirmed the three Brazilian tests, which were made independently of each other in order to determine no bias.\r\nAnd what were the results of these?\r\nThey confirmed the fact that this material was of a purity greater than the laboratory standard for pure magnesium.\r\nOh, okay, fine. That's something different.\r\nI hesitate to go on any further with these details, because no one's a specialist up here.\r\n(00:12:05)"}),(0,i.jsx)(t.p,{children:"The only thing is, this is a very exhaustive treatment of this, with all of the tables and all kinds of tests that I can't read.\r\nOnly a specialist and a scientist in this field would really understand.\r\nWell, I'm in solid state.\r\nYeah, well, this would be right up your alley.\r\nWell, I'd like to break in here. Apparently, this man's an expert on metals.\r\n(00:12:25)"}),(0,i.jsx)(t.p,{children:"I have had these tests examined by a number of metallurgists, and including some connected with the government in Newport,and their opinions are conflicting.\r\nIn other words, it's possible for different people to interpret these tests in different ways.\r\nI certainly recommend that you get a copy of the original book.\r\nI think you keep yourself fascinatingly occupied for at least a full day, maybe more.\r\n(00:12:49)"}),(0,i.jsx)(t.p,{children:"All right.\r\nOkay, Mr. Stone.\r\nAll right, thank you.\r\n(00:12:51)"}),(0,i.jsx)(t.hr,{}),(0,i.jsx)(t.p,{children:"Thank you for calling.\r\nThe hundreds and thousands of groups that have sprung up throughout the world that have made a cult,and in some cases a real religion, out of the UFO question,I'm afraid that we have been simply overwhelmed by the tremendous number of people that seem to have a need to develop some new type of religion,which is what it is really.\r\n(00:13:19)"}),(0,i.jsx)(t.p,{children:"Many groups are frankly religious.\r\nWell, now, Mr. Hoff, I hope that this program tonight, and your being on it, and Mr. Webb's,shows you that at least I'm serious about this, and I hope that this has been a small voice, and maybe not so small,in giving some of your original, and I hope not too tarnished, beliefs in what you were doing.\r\nMr. Webb, how about NICAP? Is it looking toward something of the same matter as APRO, or has it got a little different viewpoint?\r\n(00:13:46)"}),(0,i.jsx)(t.p,{children:"Well, I think it is a shame that these fan clubs, these little cult groups, have sort of confused the issue, if I may put it that way.\r\nThere are serious groups around, and I think the two that come to mind, of course, are APRO and NICAP.\r\nAs for NICAP, it has two goals, really, that I can think of.\r\nOne of them is a congressional investigation of the Air Force investigation.\r\n(00:14:19)"}),(0,i.jsx)(t.p,{children:"As to why it's been so bottled up and two-faced.\r\nAs to why everything's bottled up, and it seems that these serious civilian groups like APRO and NICAP arrive at one conclusion,and the Air Force arrives at another, at least publicly.\r\nAnd we get the impression that there are facts and information that's being withheld from the public.\r\nSo perhaps, we hate the idea, but perhaps the only way to do it would be to attempt a congressional investigation.\r\n(00:14:47)"}),(0,i.jsx)(t.p,{children:"Well, some congressmen have shown a great interest in this.\r\nThey have shown a tremendous interest in it, and I think that NICAP does have the backing.\r\nIf I may say this, NICAP is about ready to publish a report called the UFO Evidence, and it's a summary of seven years of NICAP investigations.\r\nThey will include a lot of sightings in this report, and it's due to come out early next month.\r\n(00:15:10)"}),(0,i.jsx)(t.p,{children:"We think this could be the spark. We hope that it will be the spark for Congress to get on the ball here with a possible investigation.\r\nNow, that's one goal. Through this means, perhaps a scientific investigation would be the next step.\r\nBut I think that it's got to be gotten out into the open first, and perhaps this NICAP report will do this.\r\nWhen it gets out, when the public realizes that there's something behind this secrecy that's going on, something behind the UFO story as far as that goes,then the interest may be generated, and we can hope for a scientific investigation.\r\n(00:15:49)"}),(0,i.jsx)(t.p,{children:"Good. Well, I wanted you to at least state what the two organizations were trying to do. Yes, Mr. Hoffman?\r\n(00:15:54)"}),(0,i.jsx)(t.hr,{}),(0,i.jsx)(t.p,{children:"I can't help but comment on what Walter has said. I agree completely with the purposes of NICAP.\r\nI don't want people to get the impression that I'm opposed to them. I'm a member of NICAP, and I've supported them financially.\r\nAnd I certainly hope that they could get a congressional subcommittee to investigate.\r\nHowever, I don't think this will ever come about because there are too many skeletons in the closets of the military and the Pentagon.\r\n(00:16:24)"}),(0,i.jsx)(t.p,{children:"I think that Pentagon must have 50 million closets in it.\r\nI'm afraid that any sort of an investigation that was conducted by Congress would be conducted 100% behind closed doors.\r\nThe few little inquiries that Congress has held, a few subcommittees have held investigations on this subject in the past,and the only speakers who testified at these hearings... I've said this backwards.\r\nThe only statements that were released to the press from these hearings were statements of Air Force spokesmen.\r\n(00:17:04)"}),(0,i.jsx)(t.p,{children:"With the public attitude we've already become familiar with.\r\nThat's right. And I don't give any hope to the idea that Major Kehoe has.\r\nIt's a wonderful, glorious crusade, but I don't believe that he'll ever get a congressional investigation.\r\nYou must believe. Your view is a little more cynical, perhaps, than Mr. Webb's, but then you're a little older than he is.\r\nI think I've been in the thing a little bit too long, maybe. I'm honestly weary of butting our heads up against a stone wall.\r\n(00:17:34)"}),(0,i.jsx)(t.p,{children:"We have never been able to get any coherent policy statements from the government on this subject.\r\nWell, you must believe, then, sir, that this whole investigation of UFOs, or the whole evidence such as it exists,is one which is either so secret or has such terrifying, at least in the opinion of some of our governmental leaders, perhaps military...\r\nI'm glad you said that.\r\n(00:17:56)"}),(0,i.jsx)(t.p,{children:"...implications that they feel that for our best interests they must keep it bottled up.\r\nOf course, I'll take issue with who should decide my best interests, and I gather you feel the same way.\r\nWell, one of the theories, and at one time it was my favorite theory, is that the reason the government has gone to great lengths to discredit authentic witnessesand to ignore some of the authentic evidence that we have is that the real truth about the UFO situation is simply too horrible to make public.\r\n(00:18:29)"}),(0,i.jsx)(t.p,{children:"And this is a very sad conclusion I have to come to, but I don't know what other conclusion you can reach.\r\nI hate to feel that the whole thing is being concealed because the government has made such a botch of the whole thing that they hate to have the truth come out of the mishandling of this subject.\r\nBut, gentlemen, it isn't just our Congress who can be concerned. These sightings have been all over the world, and there are other Congresses and there are other governments.\r\n(00:18:55)"}),(0,i.jsx)(t.p,{children:"Now, is there any hope here?\r\nWell, possibly. I might mention that, in fact, the Brazilian Air Force, back in 1954, and this is in direct contradiction with anything that's been released by our own Pentagon in this country,they held a press conference and released three tentative conclusions. Now, remember, this is back in 1954.\r\n(00:19:17)"}),(0,i.jsx)(t.hr,{}),(0,i.jsx)(t.p,{children:"They have since changed their tune a little bit, I think, and closed down just as the U.S. Air Force has done.\r\nBut when they were speaking openly, they said what?\r\nHere are their three conclusions. They concluded that, one, the UFOs were real, number two, they were revolutionary aircraft of some sort, and number three, that the origin was unknown.\r\nNow, they don't come right out and say that they're spaceships from another planet, but they are hinting at it, and this is certainly a step in the right direction.\r\n(00:19:50)"}),(0,i.jsx)(t.p,{children:"But you see, something's happened. Even the Brazilian Air Force has closed the lid down.\r\nYes. Gentlemen, thank you for at least making clear some of your thoughts about what this means, and I apologize to those of you who are on the phone and waiting,and we're going to get to you right away, but we do have a little message for you first.\r\n(00:20:06)"})]}),"\n",(0,i.jsx)("hr",{style:{height:"3px",borderWidth:"3px",color:"orange",backgroundColor:"blue"}}),"\n",(0,i.jsx)(t.h2,{id:"link2",children:"link2"}),"\n",(0,i.jsx)(t.h3,{id:"\u51fa\u5178",children:"\u51fa\u5178"}),"\n",(0,i.jsxs)(t.p,{children:["Ubatuba - Coral Lorenzen\r\n",(0,i.jsx)(t.a,{href:"https://www.nicap.org/reports/uba1.htm",children:"https://www.nicap.org/reports/uba1.htm"})]}),"\n",(0,i.jsx)(t.h3,{id:"\u539f\u6587",children:"\u539f\u6587"}),"\n",(0,i.jsxs)(a,{children:[(0,i.jsx)("summary",{children:"\u25bc\u5c55\u958b"}),(0,i.jsx)(t.p,{children:"Ubatuba - Coral Lorenzen\r\n18\u201322 minutes"}),(0,i.jsx)(t.p,{children:"CORAL LORENZEN AND THE UBATUBA UFO FRAGMENTS"}),(0,i.jsx)(t.p,{children:"by Robert Barrow"}),(0,i.jsx)(t.p,{children:"This article was submitted to various UFO-related publications between 1991-1994, and actually was accepted - but then rejected -- for publication in England. The apparent objections among editors were my reluctance to name names and the probability that article content would lack mass appeal among a younger readership which may not be familiar with the Ubatuba UFO case. I obviously respect editorial wishes, for editors must base their decisions on a variety of factors. However, I stand by my decision to exclude various names in the interest of privacy and fairness (and now that Coral Lorenzen is gone, I have no one to back up the story I relate), and I believe the Ubatuba case remains important enough to merit the attention of any readership intrigued by UFOs - no matter their age or knowledge of UFO history"}),(0,i.jsxs)(t.ul,{children:["\n",(0,i.jsx)(t.li,{children:"Robert Barrow, August, 2000"}),"\n"]}),(0,i.jsx)(t.p,{children:"In a perfect literary world, the editor whose desktop boasts only finely-crafted, informative articles written without any hint of writers' personal musings, whining or bitching is fortunate indeed. Alas, this submission won't altogether reach those standards."}),(0,i.jsx)(t.p,{children:"Some 28 years of serious inquiry into the nature of UFOs have afforded me the opportunity to research the subject, investigate reports, write about the phenomenon for publication, teach a course on UFO history at a college, and to be both praised and condemned by government sources for my meager contributions. At one time, and I've never mentioned it publicly before for fear of sounding like the number one traveler on an extended ego trip, I received a Congressional recommendation to serve on a government UFO research project that was only rumored and apparently never came to be."}),(0,i.jsx)(t.p,{children:"All of this may seem fabulously interesting to some, but it doesn't matter much on a resume intended for today's politically correct society in the USA, nor in many other areas. Thus, having pursued the UFO for many years and usually coming up with a hand full of thin air, yet convinced beyond doubt that the enigma is reality incarnate and likely of great significance to us all, this writer becomes increasingly content to entertain memories."}),(0,i.jsx)(t.p,{children:"Like my relationship with NICAP as a member for several years, another very influential memory will long remain my affiliation as both member and field investigator with the Aerial Phenomena Research Organization of Arizona, founded in 1952 by the late Jim and Coral Lorenzen. I joined APRO in 1965 and remained a member until Coral's death in 1988. Little did I suspect that my final contact with her in 1987 would involve the intriguing Ubatuba UFO incident and possible UFO evidence."}),(0,i.jsx)(t.p,{children:"My last contact with Mrs. Lorenzen occurred about a year before her passing. On an afternoon in May, 1987, she phoned my home, leaving a message that she very much needed to speak with me."}),(0,i.jsx)(t.p,{children:"(1) As I was away, however, I could not return her call until after 1:30 a.m. E.S.T."}),(0,i.jsx)(t.p,{children:"(2) Pleasant enough, yet obviously gravely concerned, Coral wasted little time in getting to the point: Could I help her track down a missing fragment of the (alleged) Ubatuba, Brazil UFO?"}),(0,i.jsx)(t.p,{children:'Far from conclusive as UFO evidence, the Ubatuba incident nonetheless remains a genuine puzzle to researchers. In September, 1957, a Rio de Janeiro newspaper printed an illegibly signed letter about a "flying disk" that exploded over a beach at the Sao Paulo Province of Ubatuba. Enclosed with the letter were three tiny pieces of a white metallic substance that had supposedly rained down" from the exploding object. Despite an intensive inquiry by the late Dr. Olavo Fontes, APRO\'s Brazilian representative, the witnesses to the bizarre beach event could never be identified, a dilemma that plagues the case to this day.'}),(0,i.jsx)(t.p,{children:"Scientific analysis at the time, however, certified the fragments themselves to be eminently curious, composed as some of them were of pure magnesium, a metallic element. The purity of the samples, in fact, caused some scientists to entertain an extraterrestrial source of intelligence."}),(0,i.jsx)(t.p,{children:"A number of high-tech examinations of minute pieces of the Ubatuba fragments have continued over the years; unfortunately, some of the crucial portions from early investigations were destroyed as an inevitable result of tests performed upon them. (3) The history of the Ubatuba incident is widely recounted in UFO literature, so this writer won't belabor the details, except to report that, apparently, the remaining fragments continue to provide scientists with some rather curious findings, particularly in view of what sort of things shouldn't have been able to be hoaxed, let alone manufactured, with known 1957 technology."}),(0,i.jsx)(t.p,{children:'"Listen, I may have called the wrong person," Coral explained, "but I do know that you\'re a good, faithful APRO member.. this is very important." Sinking further into my chair in the early morning New York darkness, I suddenly felt as if the anxious voice speaking from West Grape Drive in Tucson, Arizona, was hovering right at my ear, intent upon making me understand something essential. The conversation would be all the more intriguing because Coral had found it necessary to hang up from my call due to a bad connection, and then she phoned back, at which time the long distance hookup was fine - a curiosity that she firmly believed was created by a government phone tap on APRO\'s line, and a problem that recurred when I spoke with her a few days later, in fact.'}),(0,i.jsx)(t.p,{children:'APRO, she continued, was working with a physicist on a Ubatuba sample, "and we have had very good results, which I won\'t go into..." The apparent problem was that APRO needed another piece to strengthen its case - a piece that was missing.'}),(0,i.jsx)(t.p,{children:"As most of the people referred to here are still living and in many cases would find disclosure of their names most unwelcome, or at the very least unnecessary, and in an attempt to relate this story fairly, names are excluded. If participants wish to come forward in the future, that is their business. This writer is simply the messenger."}),(0,i.jsx)(t.p,{children:"As our conversation progressed, Coral recalled that in 1979 her husband Jim had loaned a Ubatuba sample to a man who writes UFO articles with some success for major publications, supposedly for additional analysis. Years later, learning of Coral's search for the fragment, the writer contacted the scientist currently working on Ubatuba evidence and stated that, indeed, he had actually returned the piece to APRO soon after obtaining it."}),(0,i.jsx)(t.p,{children:'"We know better," Coral added. "I would have known if it had come back because I log that stuff in.'}),(0,i.jsx)(t.p,{children:"Additionally, she knew that a certain other scientist acquainted with the UFO writer was to be the recipient of the fragment for examination, and upon further inquiry the APRO physicist located the scientist. He, however, insisted he had turned the piece over to another man, a UFO \"enthusiast\" who works for a large corporation, but resides in a small town. Incredibly, he couldn't even remember the man's name!"}),(0,i.jsx)(t.p,{children:'"Well, here\'s the thing." Coral went on, "(the APRO physicist) is bound and determined, and I am, too, to find this stuff," and even though their target was nameless, they knew the name of his alleged town of residence in New York State. Coral asked me to check with the local newspaper to see if anybody in town was "big on UFOs." Big on UFOs was perhaps an understatement, for, as she confided ("This is confidential") with anxiety, the guy was a "Meierer," a fan of UFO photographer/ contactee/ witness/ ambassador/ what-have-you Billy Meier, a man whose claims held no credence for her.'}),(0,i.jsx)(t.p,{children:"Even more complicating, Coral feared that the nameless man had connections with another Arizona UFO researcher whom, once a friend, she no longer trusted, concerned that he might get his hands on the Ubatuba sample for his own ends. Her one compelling wish was to retrieve the fragment and turn it over to her physicist, whom she and Jim had chosen specifically to analyze the Ubatuba material. My task was only to learn the name of the man in the small town, but to avoid contacting him so as not to alarm him. After that, Coral would make arrangements to contact him about the fragment, even if it meant someone's necessity to visit him personally. She was adamant about my not contacting him myself, but just to \"See if they know a guy who is very into the Meier case, because it seems to be that's the hooker.\""}),(0,i.jsx)(t.p,{children:'After a little more discussion about her health, Arizona weather and some particularly underhanded actions and shortcomings on the part of a UFO organization director who she despised (perhaps with excellent reason), we ended the conversation with my promise to find out what I can. I would be back in touch in a few days. I failed miserably, overwhelmingly, and discovered nothing useful. I dreaded Coral\'s certain disappointment when I phoned back several days later, (4) but before we engaged in any specifics she noted, as previously, a terrible phone line connection. "I think maybe they\'re running a tap on my line," Coral admitted. "I mean, if I turn around and call you back it\'ll be just ducky, just like before."'}),(0,i.jsx)(t.p,{children:'As previously, Coral phoned me back immediately, and this time the audio was remarkably improved. "I told you," she sighed, as if resigned to it, as if having only temporarily dispensed with a pest that always returns. "I think that my incoming calls that are long distance, they can\'t pick up - that if I dial out it\'s easier for them."'}),(0,i.jsx)(t.p,{children:"I related the empty news, the futility of my inquiry. First, there existed no newspaper at all in the town, nor broadcast stations in this area of about 1500 people. In fact, my only negligible victory occurred in a conversation with a town librarian whom, when asked about anybody she knows who might have an interest in UFOs, replied in the negative. The best she could do was to suggest contacting larger nearby areas and their newspaper editors. In fact, one location I mentioned did ring a bell with Coral, whatever she planned to do with this information."}),(0,i.jsx)(t.p,{children:'Kindly, Coral thanked me profusely even for the near-nothingness I had provided. She seemed, however, all the more furious with the UFO writer to whom Jim had originally loaned the desired Ubatuba fragment. "That damned (last name stated), I could kill him!." This was serious, considering that during our prior discussion she had merely referred to him as an S.O.B! "(Last name stated) has never done a damned thing for us. He\'s a writer, he wants to make a buck off anybody he can."'}),(0,i.jsx)(t.p,{children:'Coral calmed herself after this uncharacteristic outburst. "Well, I\'ll just tell (the physicist) that you\'ve done the best that you could." She then considered other APRO investigators who might be in a better position and closer to potential locations to check things out, and she came up with a name I knew and respected. "He knows quite a few people, that\'s the thing," she admitted.'}),(0,i.jsx)(t.p,{children:"That conversation, more than five years ago now, provided my last cherished opportunity to speak with Coral Lorenzen, and I haven't the slightest idea how her frantic search for the enigmatic Ubatuba fragment turned out. I hope she found it before her demise, especially because the Lorenzens and their associates expended considerable labor on the case over the years. At the very least, Coral certainly gave the impression that some exciting discoveries were popping up in the laboratory. Maybe an individual or two will come forth and contribute a little more insight eventually. Or maybe not."}),(0,i.jsx)(t.p,{children:'Ubatuba is an old UFO case, superceded now by stories of alien abductions, cattle mutilations, mysterious crop circles and "Andromeda Strain"-like intervention in human society on a global scale. Nevertheless, Ubatuba has a meaning on some level to UFO research, and Jim and Coral Lorenzen recognized this acutely.'}),(0,i.jsx)(t.p,{children:"So, the applicable extent of my knowledge of the search fbr the missing Ubatuba fragment having been presented, I shall end my recollections simply with the one word Coral routinely used at the termination of her notes and letters, a word that I fondly hope had some personal meaning in her final days."}),(0,i.jsx)(t.p,{children:'"Cheers."'}),(0,i.jsx)(t.p,{children:"NOTES:"}),(0,i.jsxs)(t.ol,{children:["\n",(0,i.jsxs)(t.li,{children:["\n",(0,i.jsx)(t.p,{children:"Telephone call from Coral Lorenzen on the afternoon of May 6, 1987."}),"\n"]}),"\n",(0,i.jsxs)(t.li,{children:["\n",(0,i.jsx)(t.p,{children:"Telephone call to Coral Lorenzen from approx. 1:37 to 2:00 a.m. E.S.T. on May 7, 1987."}),"\n"]}),"\n",(0,i.jsxs)(t.li,{children:["\n",(0,i.jsx)(t.p,{children:"Basic details of the Ubatuba case as mentioned here are obtained from The Encyclopedia of UFOs, ed. By Ronald Story (Ubatuba section contributed by Walter W. Walker, who analyzed a fragment himself). Dolphin Books, NY, NY, 1980, pps. 374-375."}),"\n"]}),"\n",(0,i.jsxs)(t.li,{children:["\n",(0,i.jsx)(t.p,{children:"Telephone call to Coral Lorenzen from approx. 12:48 to 12:53 a.m. E.S.T. on May 12, 1987."}),"\n"]}),"\n"]}),(0,i.jsx)(t.p,{children:"end-"})]}),"\n",(0,i.jsx)(t.p,{children:"(2025-04-25)"}),"\n",(0,i.jsx)("hr",{style:{height:"3px",borderWidth:"3px",color:"orange",backgroundColor:"blue"}}),"\n",(0,i.jsx)(t.h2,{id:"link3",children:"link3"}),"\n",(0,i.jsx)(t.h3,{id:"\u51fa\u5178-1",children:"\u51fa\u5178"}),"\n",(0,i.jsxs)(t.p,{children:["Ubatuba Case - Dow Chemical And The Scientific Analysis OF UFO Debris\r\n",(0,i.jsx)(t.a,{href:"https://www.nicap.org/reports/ubatubadow2.htm",children:"https://www.nicap.org/reports/ubatubadow2.htm"})]}),"\n",(0,i.jsx)(t.h3,{id:"\u539f\u6587-1",children:"\u539f\u6587"}),"\n",(0,i.jsxs)(a,{children:[(0,i.jsx)("summary",{children:"\u25bc\u5c55\u958b"}),(0,i.jsx)(t.p,{children:"Ubatuba Case - Dow Chemical And The Scientific Analysis OF UFO Debris\r\nAdam\r\n35\u201344 minutes"}),(0,i.jsx)(t.p,{children:"Dow Chemical"}),(0,i.jsx)(t.p,{children:"and the Scientific Analysis of UFO Debris"}),(0,i.jsx)(t.p,{children:"by Joel Carpenter"}),(0,i.jsx)(t.p,{children:"Most students of the history of UFOs are familiar with the famous Ubatuba, Brazil case of 1957, in which metallic debris said to have been retrieved after the explosion of a UFO was determined to be magnesium metal of unusual composition. Few researchers are probably aware of another, surprisingly similar incident that occurred in the US at the dawn of the modern UFO phenomenon. This incident directly or indirectly involved a host of people and organizations that were later to have a major impact on the study of UFOs in the United States, and points out that there is still much to be learned concerning the early investigation of the phenomenon by the military, the intelligence community and even, perhaps, by the corporate world."}),(0,i.jsx)(t.p,{children:"Project Blue Book's detailed case file on the second incident tells a weird and fascinating tale. According to Dow documents preserved in the file, the event began just after 5:00 on the afternoon of July 9, 1947, when a forty-five year old electrician named Raymond Lane and his wife were picking huckleberries near Midland, Michigan. A strange sizzling noise abruptly drew their attention to a bizarre mass of bright white, fiery sparks hovering about a foot above the ground and about a hundred feet away. It reminded them of a Fourth of July sparkler, but it was much bigger -- the size, as they later put it, of a bushel basket. The fireball burned brilliantly for about fifteen seconds before dying out. When the smoke drifted away, there was nothing left except some hot, light-and-dark-colored metallic-looking debris on the sandy soil. Lane collected fragments of the material in a tin can and considered whom to tell."}),(0,i.jsx)(t.p,{children:"The mysterious fireball had appeared in a uniquely appropriate place. Midland happened to be the home of one of America's most well-equipped materials analysis facilities: the laboratories of Dow Chemical company, well known for its metallurgical expertise and a world leader in magnesium technology."}),(0,i.jsx)(t.p,{children:"Shortly after World War I, Dow metallurgists had developed an alloy that the company called \"Dowmetal\" -- refined magnesium to which was added about six percent aluminum and one-half percent manganese. Dowmetal was widely promoted for automotive and aviation uses and was highly profitable for the company, eventually giving it a virtual monopoly on magnesium production in the US. In 1933 the company was approached by Belgian scientist Jean Piccard with a request to design and build a Dowmetal cabin for a record-setting high-altitude balloon flight. The design was highly successful and eventually enabled flights to over 70,000 feet. During World War II Dow's extremely lightweight, strong magnesium alloys became an indispensable ingredient of aircraft and missile structures. The company also became a contractor for an unusual flight test program that had a direct link to Project SIGN, the Air Force's 1948 UFO research establishment."}),(0,i.jsx)(t.p,{children:"See: Dow and Boundary Layer Control"}),(0,i.jsx)(t.p,{children:'One of the most significant figures behind Dow\'s success was a chemist named John Josef Grebe [pronounced "gree-bee"]. Born Hans Josef Grebe in Uerzig, Germany in 1900, he emigrated to Ohio in 1914 and became a US citizen in 1921. Grebe graduated from the Case School of Applied Science in 1924 and was immediately hired by Dow. Considered a genius by his colleagues and known as the "Idea Man," Grebe was given free rein to work on projects of his own devising. He established the company\'s Physical Research Laboratory, an organization that produced a steady stream of valuable inventions, particularly in the field of plastics. Chemists under his direction were responsible for the discovery of several now-universally used plastics, such as styrene, Styrofoam, and polyvinyl chloride, and also developed a synthetic rubber that was vital to the US military in World War II.'}),(0,i.jsx)(t.p,{children:"Grebe even perfected a method of extracting magnesium from sea water, a process that became Dow's main source of the metal. After Japan's surrender Grebe was assigned to work with the Oak Ridge nuclear laboratory, and in 1946 he was an observer at the Operation Crossroads nuclear tests. He also worked closely with the US Army's Chemical Corps on the highly classified toxicological and radiological warfare programs (in fact, by 1948, Grebe would be named the Chemical Corps' chief technical advisor)."}),(0,i.jsx)(t.p,{children:"The morning after the fireball incident, Lane took his can of sandy debris to Robert S. Spencer, a senior researcher in Grebe's laboratory, whom Lane had met when he was a Dow employee some years before. Spencer contacted Edward Fales, the company's internal security chief, and together the men went to the site to investigate. Lane told the Dow officials that he thought the object had been a flying saucer, or possibly a meteorite, and that some small lumps of silvery metal in the debris he had scooped up might be platinum. (Ironically, there is no evidence that he or anyone else ever reported seeing an object in flight prior to the appearance of the fireball). Spencer immediately arranged to have the material analyzed. The Spectroscopy Laboratory quickly reported that the shiny pellets in the material were largely silver mixed with a few percent silicon, which probably came from the sand on which the molten material had solidified. The sample was checked for radioactivity, but did not blacken photographic plates. According to a report by Fales,"}),(0,i.jsx)(t.p,{children:"Preliminary tests of the material show the contents to be as follows: ordinary sand, not radio active [sic], but giving off an ammonia gas. A silver nugget, almost pure except for sand mixed in it, not radio active. Melted or fused sand which gives off ammonia, has little droplets of silver melted in the sand and some other material which is not radio active. The fused sand has some characteristics of the Los Alamos sand [i.e., the glassy material created by the Trinity nuclear explosion] but is not believed to be the same."}),(0,i.jsx)(t.p,{children:"By the end of September the Lab had run more spectrographic tests on a small quantity of a fine, light, ash-like powder laboriously sifted from the debris. The powder turned out to be a material called thorite, which was discovered to be somewhat radioactive. The remaining portion of the debris yielded traces of iron, aluminum, magnesium, and other metals. There was also evidence of a significant amount of magnesium hydroxide, which some analysts took to be the remains of the combustion of a sizable amount of magnesium."}),(0,i.jsx)(t.p,{children:"Interestingly, Dow handled the case as a purely internal matter at first. Fales' inquiries concerning Lane led him to conclude that he was a somewhat peculiar individual who was known to have basic technical expertise. On balance, the incident seemed likely to be the result of some kind of home-made fireworks experiment. The FBI was eventually contacted and an agent conducted a basic inquiry. As will be seen, there was no Air Force involvement with the case in 1947."}),(0,i.jsx)(t.p,{children:"Activity surrounding the Midland fireball incident became dormant by the autumn of 1947 but was revived dramatically a year later, when on September 17, 1948, Grebe, then working with the Chemical Corps at Edgewood Arsenal, Maryland, requested an update on the investigation from Dow. An examination of Fales' dossier set him to speculating. In an October 11 memo to one of his Army superiors, he wrote that"}),(0,i.jsx)(t.p,{children:"The only technical point that would tend to discredit the report in a very slight way is that the particular spectrum analysis that was made of the sand that was supposed to have been picked up with the sample of the fused mineral matter, which contained nuggets of silver, had a different analysis from the sand picked up in the general area. It had rained, however, in the meantime, which would remove any magnesium hydroxide that might have been around."}),(0,i.jsx)(t.p,{children:"As a whole, it would appear to me that, every bit of evidence found should be considered seriously as an indication that a self-consuming missile capable of producing a considerable amount of smoke and fire and leaving behind only the minimum residue required to produce a battery and radio transmitter is feasible and was probably observed."}),(0,i.jsx)(t.p,{children:'This concept - that the small Midland fireball had represented the self-destruction of some kind of instrumented projectile - marked a drastic change in the official approach to the incident, bringing it in line with the fears in 1946 and 1947 that some anomalous meteor-like events were actually a type of "self-consuming missile" experiments.'}),(0,i.jsx)(t.p,{children:"See: Ghost Rockets"}),(0,i.jsx)(t.p,{children:"See: Green Fireballs"}),(0,i.jsx)(t.p,{children:"It is not apparent from the available source material exactly why Grebe chose this juncture to reopen the case, but there are indications that similar studies were being performed at the time on other samples of apparent UFO debris that were considered to be possibly the remains of missiles. For example, on November 26, FBI Director J. Edgar Hoover sent a memo to the Air Force's Director of Special Investigations (IG), concerning a case similar to the Midland incident."}),(0,i.jsx)(t.p,{children:'Just two days before Lane\'s 1947 experience, a group of people near the village of West Rindge, New Hampshire had been surprised by the sudden appearance of wisps of smoke and flame rising from nearby lawns and fields. Many small burned areas were discovered to be scattered in a 200-foot diameter circle and seemed to have been caused by hot fragments of metal that apparently had fallen from the sky. A witness turned several of the fragments over to a Professor "Rentges" of the Massachusetts Institute of Technology for analysis. (This was typical phonetic FBI spelling -- "Rentges" was apparently J. Francis Reintjes of the MIT Servomechanisms Laboratory where Project Whirlwind, a powerful digital computer that would become the prototype for the SAGE national air defense network, was under development at the time). Reintjes expressed the opinion that the material, which had obviously been subjected to "terrific heat," resembled the lining of the rocket engines of German V-2 ballistic missiles he had seen in New Mexico. Four of the collected fragments, when pieced together, appeared to have been part of a hollow cylinder eight inches in diameter and having a wall thickness of three-sixteenths of an inch. The West Rindge material had been subjected to spectrographic analysis recently, Hoover reported, and was determined to be ordinary cast iron that "had been subjected to a very high degree of heat."'}),(0,i.jsx)(t.p,{children:'Additionally, in a letter titled "Flying Object Incidents in the United States", dated November 3, 1948, Col. Howard McCoy of Air Materiel Command\'s Technical Intelligence Division informed Chief of Staff General Hoyt Vandenberg that his Project "Sign" flying saucer analysts had interviewed Dr Irving Langmuir of General Electric concerning the possible origin of the objects, and that "it is planned to have another interview with Dr. Langmuir in the near future to review all the data now available, and it is hoped that he will be able to present some opinion as to the nature of the unidentified objects, particularly those described as \'balls of light.\'"'}),(0,i.jsx)(t.p,{children:'Study of this particular type of flying object - apparently a tiny, remote-controlled or internally-guided probe - had gained urgency after the October 1, 1948 incident in which an Air National Guard pilot had engaged in a long nighttime dogfight over Fargo, North Dakota with a small, fast-moving blinking light that was apparently under intelligent control. It seems probable that this effort to carefully analyze fragments of suspected flying saucers was part of the escalating attempt to establish whether there was any credible evidence of a foreign terrestrial origin of the objects - an approach that achieved its highest expression with the publication, on December 10, 1948, of the Top Secret Air Intelligence Division Study 203, "Analysis of Flying Object Incidents in the US". This study examined the possibility that flying objects reported over the continental US represented Soviet reconnaissance, training or provocation missions.'}),(0,i.jsx)(t.p,{children:"Meanwhile, John Grebe had taken his theory about the Midland case to the highest levels of Army missile research. In the middle of October he met with Col. Holger Toftoy, Army Ordnance, the commander of Project Hermes, the Army's multifaceted guided missile program based at White Sands, New Mexico. Shortly after the Nazi surrender Toftoy had supervised the removal of some one hundred V-2 missiles from underground factories and had them transported to White Sands. Under Project Paperclip, the German rocket engineers who had created the V-2, including Wernher von Braun, were moved to Fort Bliss to work with Toftoy's Ordnance team and General Electric, the contractor for Project Hermes, in reconstructing and launching the missiles."}),(0,i.jsx)(t.p,{children:"Toftoy's log for October 18, 1948 records Grebe's surprising presentation:"}),(0,i.jsx)(t.p,{children:'Conference attended by Cols Toftoy, Roberts & Bainbridge (CC), Maj J.F. Gay & Dr. J. J. Grebe, (Chemical Corps), and Dr. Mugson. Chemical Corps reported analysis of fragments picked up from \'"flying saucer" which vanished with a brilliant flash and bang near Midlin [sic], Michigan. Sand and clinker recovered from the locality contained nuggets of fairly pure silver and some thorium. The thorium was sufficient to give radio activity [sic] approximately 10 times natural background which could possibly be ascribed to thorium coated filaments in electronic equipment, although the quantity seems excessive. There was evidence also of mechanism [magnesium] which had been completely oxidized. Dr. Grebe advanced his hypothesis that small missiles of the order of 1 to 3 feet in diameter might be responsible, coming from distant sources. He considered that a rapidly rotating disc of mechanism [magnesium] and/or aluminum might have enough energy if properly utilized to propel the disc several thousand miles, and might be completely destroyed by burning in air. Remaining traces of silver and thorium might be ascribed to electronic control system. After discussion, it was agreed that Col Roberts should request the Bur of Standards group to investigate some of the mechanisms which might conceivably propel discs of this general type and TU will keep in close touch with these calculations (CMH). A meeting next Monday, 25 Oct, can be arranged with Dr. Grebe if indications are favorable. Dr. Grebe also briefly described a theory of his that a fish-shaped object with a modified tear-drop cross section would take off along the long axis and change position in flight to fly at an angle more like a flying wing. No wings or other aerodynamic surfaces that produce drag would be required.'}),(0,i.jsx)(t.p,{children:'Grebe clearly envisioned the Midland object as a small, unmanned vehicle containing 1940s state-of-the-art vacuum tube based electronic equipment, and given that he specified its range as "thousands of miles," he apparently believed that its source was the Soviet Union. The intriguing vision of a fast-spinning, flywheel-like object that would destroy itself at the end of its trajectory was novel, to say the least, but Grebe had a good reason for this idea. One of Dow\'s most secret and most vital wartime projects had been the development of a structural housing for the miniature radio transmitter that formed the heart of the "VT" - the proximity fuse.'}),(0,i.jsx)(t.p,{children:"The radar like VT fuse was designed to detonate an artillery shell at the exact moment that it passed within lethal range of its target, such as an aircraft or missile - or in anti-personnel applications, just as it descended to within a few yards of the ground. To do so, it incorporated a tiny radio transmitter and receiver built from highly miniaturized and ruggedized vacuum tubes. These tubes had to survive shock and acceleration amounting to thousands of g's when fired from a heavy gun, as well as the enormous centrifugal force of the shell's stabilizing spin. Dow's contribution was the design and production of a special plastic housing for the tiny tubes, and the project was carried out in such secrecy that most of the technicians on the project only learned of its exact function at the end of the war."}),(0,i.jsx)(t.p,{children:"(The proximity fuse design effort was headquartered at the Johns Hopkins University's Applied Physics Laboratory in Maryland and was directed by Merle Tuve, whose administrative assistant was an astronomer named Josef Allen Hynek.) Grebe's saucer concept amounted to something much like an artillery shell, possibly combined with an aerodynamic shape that would allow a degree of flight after the device arrived in the vicinity of its target. The VT shell had incorporated a novel battery that was energized when its chemicals mixed due to the shock of launching, and Grebe believed that the disc-missiles used something similar. Presumably the self-destructing feature would prevent US analysts from recovering intact specimens of the vehicle."}),(0,i.jsx)(t.p,{children:'The "Bur of Standards group" referred to in the memo was the National Bureau of Standards\' Ordnance Development department, a secret guided missile research establishment operating within the weights-and-measures agency, which had worked closely with the Army and Navy during WWII under the direction of Harry Diamond and Dr. A. V. Astin.'}),(0,i.jsx)(t.p,{children:'The Ordnance department\'s first products were highly classified miniature radio components for the proximity fuse. Diamond\'s group, along with Hugh Dryden, from the Bureau\'s Mechanics and Sound department, also developed some of America\'s first "smart weapons" during the war, including the "Robin," a television-guided bomb, the "Pelican," a passive-radar-homing glide bomb, and the "Bat," a 1,000-pound radar-guided anti-ship glide weapon.'}),(0,i.jsx)(t.p,{children:"To help pack more and more electronic components into missiles, the Bureau had perfected increasingly miniaturized vacuum tubes, and by the end of the war, its technicians helped invent a process for literally painting circuitry onto insulating substrates, the forerunner of modern printed circuits."}),(0,i.jsx)(t.p,{children:"The Director of the Bureau of Standards since November 1945 was Edward U. Condon. The New Mexico-born physicist had been J. Robert Oppenheimer's roommate at the University of G\xf6ttingen, Germany, in the 1920s. He co-founded the MIT Radiation Laboratories and did fundamental work on radar theory and application at Westinghouse. When General Leslie Groves set up the Los Alamos laboratory of the Manhattan Project in 1943, he had asked Condon to be associate director under Oppenheimer. Later Condon had been a member of the executive committee of the National Advisory Committee on Aeronautics (NACA), the forerunner of NASA."}),(0,i.jsx)(t.p,{children:"When Condon left the Bureau of Standards in 1951, it was to become head of research and development at Corning Glass Works, a corporate relative of Dow (via the Dow Corning partnership). In light of the Air Force - sponsored University of Colorado UFO study in the 1960s which Condon directed (and during which his personal antipathy to the subject became legendary), it is tempting to speculate that Condon's involvement with UFOs actually might have begun a decade and a half earlier."}),(0,i.jsx)(t.p,{children:"Unfortunately, there is as yet no evidence that the Bureau of Standards \"disc propulsion study\" that Toftoy advocated actually was undertaken. Interviews with several surviving members of the Bureau's Ordnance and Electronics departments have uncovered no recollection of any such project. Grebe's theory did, however, make enough of an impression at senior military levels that a report quickly reached General Vandenberg's office. Vandenberg cabled Project Sign on December 2 inquiring about Sign's investigation of the case. Project Sign admitted in a December 21 teletype that it had no details on the Midland incident and sheepishly requested copies of Grebe's report from the Chief of Staff."}),(0,i.jsx)(t.p,{children:'Interestingly, there is some evidence that the Bureau of Standards was involved with yet another case concerning magnesium from a UFO. In 1952, five NBS scientists allegedly analyzed a fragment of metal supplied by Cdr. Alvin Moore, USN, who said that it had fallen on his property during the July 1952 "Washington, DC Invasion". The scientists subjected the material to a battery of tests, including spectrographic analysis, and concluded that it was an artificially produced artifact. It was composed mostly of magnesium, had a specific gravity of 3.48 and was filled with millions of microscopic iron particles. Like the West Rindge fragments, it appeared to be a section of a cylinder, which when complete would have been 10.4 inches in diameter. Cdr. Moore decided that Project Blue Book should know about the discovery. He mailed it to Captain Edward Ruppelt, who sent it on to the Battelle Memorial Institute, where Howard Cross gave it a cursory examination.'}),(0,i.jsx)(t.p,{children:"There are hints that Harry Diamond Laboratories, which eventually spun off from the Bureau of Standards to become part of the Army Research Laboratories, conducted a study of radar UFOs at some point in the early 1960s, but hard evidence is unavailable to date."}),(0,i.jsx)(t.p,{children:"Dow's 1947 analysis of magnesium debris from a suspected UFO crash near its own headquarters foreshadows the company's involvement with the far more famous Ubatuba material. These fragments first surfaced in September 1957 (although other accounts exist - see Sources), when they were mailed anonymously to a reporter for a Rio de Janeiro newspaper, who in turn passed them to Dr Olavo Fontes, the Brazilian representative of the Aerial Phenomena Research Organization (APRO). Coral and Jim Lorenzen, APRO's directors, were impressed by an analysis performed at a laboratory in Brazil, and upon obtaining the samples, Coral Lorenzen arranged to have Dow's magnesium experts study them."}),(0,i.jsx)(t.p,{children:"The fragments probably reached the US immediately after the launch of the Soviet satellite Sputnik on October 4, and it seems likely that there was suspicion in some US circles that the Ubatuba episode could be related in some way to Soviet intercontinental ballistic missile experiments. Soviet Premier Khrushchev had boasted in August that his new ICBM could strike any point on earth, and now it had been used to launch a globe-circling satellite. In the feverish atmosphere of the post-Sputnik US defense community, no one could afford to overlook intelligence leads -- even tenuous ones. On December 1, 1957, US Army ground search parties were called out in Alaska after sightings of unusual meteors raised suspicions that part of the Sputnik launcher rocket had entered the atmosphere there."}),(0,i.jsx)(t.p,{children:"See: The Last Ghost Rocket: Did the Sputnik 1 Launcher Fall in Alaska?"}),(0,i.jsx)(t.p,{children:'The unusually high purity of the UFO-related magnesium detected by the Brazilian laboratory may have set off alarms in the US, and part of the debris was conveyed to Dow for analysis. Similar searches for fragments of downed Soviet spacecraft became quite frequent in the 1960s and 70s and would become known as "Moon Dust" events.'}),(0,i.jsx)(t.p,{children:"See: Moon Dust events"}),(0,i.jsx)(t.p,{children:"In 1967, under the auspices of the Air Force-sponsored UFO study based at the University of Colorado and headed by Edward Condon, investigator Dr. Roy Craig obtained a portion of one of the Ubatuba fragments in order to subject it to neutron activation analysis. Since the Brazilian analysis in 1957 had indicated that the material was extremely pure magnesium - purer than terrestrial technology could produce, according to APRO - Craig contacted Dr. R. S. Busk, head of Dow's Metal Products Department."}),(0,i.jsx)(t.p,{children:"During or shortly after World War II, Dow had developed a sublimation refining process under which magnesium was heated to vapor and condensed in a vacuum chamber. After three such cycles, the material, for all practical purposes, was pure magnesium with only the most minute residue of other elements. Busk supplied Craig with triply-sublimed material as a reference sample, and while doing so, mentioned Dow's earlier test of the Ubatuba material. In a letter to the author, Craig recalled that"}),(0,i.jsx)(t.p,{children:"[P]ersonnel at the Dow laboratories were interested in UFO-related materials. They were most cooperative in furnishing pure magnesium samples and doing whatever analytical work I requested relating to the Ubatuba magnesium samples. I was surprised to learn that, years previously [possibly as early as 1958 - JC], they had done metallographic studies of the very samples of Ubatuba magnesium I was then asking them to analyze. They showed me the results of their earlier work, which they still had on file, and repeated the work for me."}),(0,i.jsx)(t.p,{children:"Interestingly, Craig himself had worked for Dow for eight years at the Atomic Energy Commission's Rocky Flats Weapons Plant in Colorado, which was a Dow-managed facility that John Grebe had helped establish. Craig did not know Grebe, but they had mutual friends. He had never heard of the Midland case, and, perhaps not surprisingly, has no recollection of Condon describing any earlier involvement with UFO research."}),(0,i.jsx)(t.p,{children:"The neutron activation analysis Craig oversaw showed that, in contradiction to the Brazilian claims, the Ubatuba sample contained more impurities than the triply-sublimed sample, and could in fact have been made by terrestrial technology. Controversy over the significance of the particular constituents of the Ubatuba sample continues, as does analysis of the material using the latest techniques."}),(0,i.jsx)(t.p,{children:"1958 advertisement for Dow magnesium cruise missile components"}),(0,i.jsx)(t.p,{children:"Grebe continued to work on nuclear projects at Dow until he retired. He died in Sun City, Arizona in 1984. His younger brother Carl, a scientist himself, recalls discussing flying saucers with John in the 1940s, and though they never discussed the Midland incident in detail, he agrees with John's former Dow colleagues that the spinning, self-destructing missile described in the Toftoy memo is exactly the kind of idea that Grebe's fertile mind would produce. The parallels between the Midland and Ubatuba incidents, separated by a decade and by thousands of miles, are striking. Were both incidents simply hoaxes, or is there still more to be learned about Ubatuba? Even Dr. Olavo Fontes observed, in his report on the Brazilian analysis of the Ubatuba fragments, that"}),(0,i.jsx)(t.p,{children:"The mystery of that sudden explosion probably will never be solved. It may have been produced by the release of some self-destructing mechanism to prevent the machine from falling into our hands and thus giving us the chance to learn its secrets."}),(0,i.jsx)(t.p,{children:"Sources"}),(0,i.jsx)(t.p,{children:"Cochrane, Rexmond C., Measures for Progress. A History of the National Bureau of Standards, NBS Special Publication 275. Washington, DC: U.S. Government Printing Office, 1966"}),(0,i.jsx)(t.p,{children:"Ray Boundy and J. Lawrence Amos, eds, A History of the Dow Chemical Physics Lab: The Freedom to Be Creative. New York: Marcel Dekker. 1990"}),(0,i.jsx)(t.p,{children:"Brandt, E. N., Growth Company: Dow Chemical's First Century. East Lansing, MI: Michigan State University Press, 1997"}),(0,i.jsx)(t.p,{children:'US Air Force Project Blue Book "July 9, 1947 Midland, Michigan" case file'}),(0,i.jsx)(t.p,{children:"Col Holger Toftoy daily log, October 1948"}),(0,i.jsx)(t.p,{children:'Note: While the Ubatuba material is typically said to have first surfaced in September 1957, some sources link its origin to much earlier Brazilian "mystery crashed airplane" stories from the pre-WWII period. Until better information is available, I assume that the 1957 version is correct.'})]}),"\n",(0,i.jsx)("hr",{style:{height:"3px",borderWidth:"3px",color:"orange",backgroundColor:"blue"}}),"\n",(0,i.jsx)(t.h2,{id:"link4",children:"link4"}),"\n",(0,i.jsx)(t.h3,{id:"\u51fa\u5178-2",children:"\u51fa\u5178"}),"\n",(0,i.jsxs)(t.p,{children:["Ubatuba Case - Composition Analysis Of The Brazilian Magnesium\r\n",(0,i.jsx)(t.a,{href:"https://www.nicap.org/reports/ubatubanal.htm",children:"https://www.nicap.org/reports/ubatubanal.htm"})]}),"\n",(0,i.jsx)(t.h3,{id:"\u539f\u6587-2",children:"\u539f\u6587"}),"\n",(0,i.jsx)("hr",{style:{height:"3px",borderWidth:"3px",color:"orange",backgroundColor:"blue"}}),"\n",(0,i.jsx)(t.h2,{id:"link5",children:"link5"}),"\n",(0,i.jsx)(t.h3,{id:"\u51fa\u5178-3",children:"\u51fa\u5178"}),"\n",(0,i.jsx)(t.p,{children:(0,i.jsx)(t.a,{href:"https://www.nicap.org/papers/scientificexploration.org_journal_jse_18_2_kaufmann.pdf",children:"https://www.nicap.org/papers/scientificexploration.org_journal_jse_18_2_kaufmann.pdf"})}),"\n",(0,i.jsxs)(t.p,{children:["On Events Possibly Related to the \u2018\u2018Brazil Magnesium\u2019\u2019\r\nPIERRE KAUFMANN\r\nCentro de R\u03bcdio-Astronomia e Astrof\xedsica Mackenzie, Universidade Presbiteriana\r\nMackenzie, Rua da Consola\xe7\xbco 896, S\xbco Paulo, SP 01302-907, Brazil\r\ne-mail: ",(0,i.jsx)(t.a,{href:"mailto:kaufmann@craae.mackenzie.br",children:"kaufmann@craae.mackenzie.br"}),"\r\nPETER A. S TURROCK\r\nCenter for Space Science and Astrophysics\r\nStanford University, Stanford, CA 94305\r\ne-mail: ",(0,i.jsx)(t.a,{href:"mailto:sturrock@flare.stanford.edu",children:"sturrock@flare.stanford.edu"}),"\r\nAbstract\u2014Inquiries in the Ubatuba area have yielded evidence of three aerial\r\nevents that may be related to an unusual magnesium specimen, which is usually\r\nattributed to an event in or near Ubatuba, an analysis of which has been\r\npublished in this journal. There is undisputed evidence that an aircraft crashed\r\nin that area in April 1957. There is strong evidence that a meteorite, or an object\r\nresembling a meteorite, crashed or exploded in the area in the early 1930\u2019s, and\r\nthat a piece of strange light-weight material was caught in a fishing net at about\r\nthat time. There is weaker evidence (mainly from one witness) that a very large\r\nobject disintegrated, with a silent explosion, near Ubatuba in or about 1957.\r\nThere is some evidence that, in or about 1957, one or more metal specimens\r\nwere brought for analysis to an Air Force research center near S\xbco Paulo and\r\nfound to be magnesium.\r\nKeywords: UFOs\u2014unidentified aerial phenomena\u2014meteorology"]}),"\n",(0,i.jsx)("hr",{style:{height:"3px",borderWidth:"3px",color:"orange",backgroundColor:"blue"}}),"\n",(0,i.jsx)(t.h2,{id:"link6",children:"link6"}),"\n",(0,i.jsx)(t.h3,{id:"\u51fa\u5178-4",children:"\u51fa\u5178"}),"\n",(0,i.jsxs)(t.p,{children:["ubatuba - Gildas Bourdais\r\n",(0,i.jsx)(t.a,{href:"https://www.nicap.org/reports/ubatubagb.htm",children:"https://www.nicap.org/reports/ubatubagb.htm"})]}),"\n",(0,i.jsx)("hr",{style:{height:"3px",borderWidth:"3px",color:"orange",backgroundColor:"blue"}}),"\n",(0,i.jsx)(t.h2,{id:"link7",children:"link7"}),"\n",(0,i.jsx)(t.h3,{id:"\u51fa\u5178-5",children:"\u51fa\u5178"}),"\n",(0,i.jsxs)(t.p,{children:["Ubatuba UFO Fragments - 1957\r\n",(0,i.jsx)(t.a,{href:"https://www.ufocasebook.com/ubatuba.html",children:"https://www.ufocasebook.com/ubatuba.html"})]}),"\n",(0,i.jsx)(t.p,{children:"(2024-08-28)"})]})}function c(e={}){const{wrapper:t}={...(0,o.R)(),...e.components};return t?(0,i.jsx)(t,{...e,children:(0,i.jsx)(d,{...e})}):d(e)}},28453:(e,t,a)=>{a.d(t,{R:()=>r,x:()=>s});var n=a(296540);const i={},o=n.createContext(i);function r(e){const t=n.useContext(o);return n.useMemo((function(){return"function"==typeof e?e(t):{...t,...e}}),[t,e])}function s(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(i):e.components||i:r(e.components),n.createElement(o.Provider,{value:t},e.children)}},669114:e=>{e.exports=JSON.parse('{"permalink":"/ds/blog/2025/04/25/ubatuba","source":"@site/blog/2025-04-25-ubatuba.md","title":"Ubatuba \u306e\u843d\u4e0b\u7269\u306e\u5206\u6790\u7d50\u679c","description":"\u524d\u7f6e\u304d","date":"2025-04-25T00:00:00.000Z","tags":[{"inline":false,"label":"UFO","permalink":"/ds/blog/tags/UFO","description":"UFO \u95a2\u9023"},{"inline":false,"label":"2025-04","permalink":"/ds/blog/tags/2025-04","description":"2025-04"}],"readingTime":52.09,"hasTruncateMarker":true,"authors":[],"frontMatter":{"tags":["UFO","2025-04"]},"unlisted":false,"prevItem":{"title":"1950, Farmington, NM: \u8ecd\u304c\u64ae\u5f71\u3057\u305f UFO \u5199\u771f\u3092\u898b\u305f\u3068\u3044\u3046\u8a3c\u8a00","permalink":"/ds/blog/2025/04/25/ms_farmington"},"nextItem":{"title":"\u7c73\u8ecd\u7a7a\u6bcd\uff08USS Franklin D. Roosevelt\uff09\u304c\u4f55\u5ea6\u3082 UFO \u306b\u906d\u9047 \uff08\u66f8\u5f0f\u5909\u63db\uff0b\u6587\u5b57\u8d77\u3053\u3057\uff09","permalink":"/ds/blog/2025/04/25/uss_dfr_ufo"}}')}}]);